#pragma once

#include <cstdint>

namespace ui {

// One character of a 1-bit bitmap font (generated by tools/fontgen).
struct Glyph {
  uint32_t codepoint;
  uint32_t offset;  // first byte in Font::bitmaps
  uint8_t width;    // bitmap size in pixels
  uint8_t height;
  int8_t left;          // bitmap position relative to the pen on the baseline
  int8_t top;           // (top < 0: above the baseline)
  uint16_t advance_x8;  // pen advance in 1/8 pixel
};

// Bitmap font: glyphs sorted by codepoint; each glyph's pixels are packed
// row by row, most significant bit first, without row padding.
struct Font {
  const char* name;
  const Glyph* glyphs;
  uint16_t glyph_count;
  const uint8_t* bitmaps;
  uint8_t size;        // pixel size the font was generated for
  uint8_t ascent;      // pixels above the baseline
  uint8_t descent;     // pixels below the baseline
  uint8_t cap_height;  // height of capital letters
};

// Glyph for a codepoint; characters missing from the font use '?'.
const Glyph& findGlyph(const Font& font, uint32_t codepoint);

}  // namespace ui
